package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.collaboration.assignmentrubric.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class AssignmentRubricStoreIntegrationTest {
 AssignmentStoreIntegrationTest f;AssignmentRubricStore store;UUID assignment;
 @BeforeEach void setup(){f=new AssignmentStoreIntegrationTest();f.setup();assignment=f.create(f.f.key()).assignment().assignmentId();store=new AssignmentRubricStore(f.f.source,f.store,Clock.systemUTC());}
 List<AssignmentRubricInput.Item> initial(){return List.of(new AssignmentRubricInput.Item(null,"Clarity <script>","설명",60),new AssignmentRubricInput.Item(null,"Evidence","Sources",40));}
 List<AssignmentRubricInput.Item> items(AssignmentRubricStore.Rubric v,String description){return v.criteria().stream().map(n->new AssignmentRubricInput.Item(n.criterionId(),n.title(),description,n.maxPoints())).toList();}
 AssignmentRubricStore.View change(long version,long parent,List<AssignmentRubricInput.Item> criteria){return store.change(f.group,f.space,f.study,assignment,f.f.owner,version,new AssignmentRubricInput(parent,criteria),f.f.trace);}
 AssignmentRubricStore.View get(){return store.get(f.group,f.space,f.study,assignment,true);}
 AssignmentRubricStore.History history(long before,int limit){return store.history(f.group,f.space,f.study,assignment,before,limit);}
 void status(int code,org.junit.jupiter.api.function.Executable action){f.status(code,action);}
 @Test void optionalAbsentAndInitialEmptyNeverAllocate(){assertNull(get().rubric());assertTrue(get().canWrite());assertFalse(store.get(f.group,f.space,f.study,assignment,false).canWrite());assertNull(change(0,1,List.of()).rubric());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM assignment_rubric WHERE assignment_id=?",Integer.class,assignment));}
 @Test void currentFullRevisionAndProtobufPreserveOrderedCriteriaAndDefinitionSource()throws Exception{var v=change(0,1,initial()).rubric();assertEquals(7,v.rubricId().version());assertTrue(v.criteria().stream().allMatch(n->n.criterionId().version()==7));assertNotEquals(v.criteria().get(0).criterionId(),v.criteria().get(1).criterionId());assertEquals(100,v.criteria().stream().mapToInt(AssignmentRubricStore.Criterion::maxPoints).sum());assertEquals(1,v.assignmentVersion());assertEquals(f.f.owner,v.creatorId());assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());var e=AssignmentRubricEnvelopeV1.parseFrom(f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.rubricId()));var p=AssignmentRubricSnapshotV1.parseFrom(e.getPayload());assertEquals("AssignmentRubricDefined",e.getEventType());assertEquals("AssignmentRubric",e.getAggregateType());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.f.owner.toString(),e.getActorId());assertEquals(v.criteria().getFirst().criterionId().toString(),p.getCriteria(0).getCriterionId());assertEquals(v.criteria().getFirst().title(),p.getCriteria(0).getTitle());assertEquals(60,p.getCriteria(0).getMaxPoints());assertEquals(1,p.getAssignmentVersion());assertEquals(1,f.store.get(f.group,f.space,f.study,assignment).version());assertEquals(1,f.parent.store.get(f.group,f.space,f.study).version());}
 @Test void idsSurviveEditsReorderingAndNoOpButStaleAlwaysFails(){var a=change(0,1,initial()).rubric();var b=change(1,1,items(a,"Same")).rubric();assertEquals(a.criteria().getFirst().criterionId(),b.criteria().getFirst().criterionId());assertEquals(2,b.version());assertEquals(b,change(2,1,items(b,"Same")).rubric());status(412,()->change(1,1,items(b,"Same")));var reversed=new ArrayList<>(items(b,"Same"));Collections.reverse(reversed);var c=change(2,1,reversed).rubric();assertEquals(a.rubricId(),c.rubricId());assertEquals(a.criteria().getLast().criterionId(),c.criteria().getFirst().criterionId());assertEquals(a.createdAt(),c.createdAt());assertEquals(3,c.version());assertEquals(3,f.events(c.rubricId()));}
 @Test void clearIsAuditedAndRemovedOrForeignCriterionIdsCannotBeResurrected(){var a=change(0,1,initial()).rubric();var empty=change(1,1,List.of()).rubric();assertEquals(a.rubricId(),empty.rubricId());assertTrue(empty.criteria().isEmpty());assertEquals(empty,change(2,1,List.of()).rubric());status(409,()->change(2,1,items(a,"Old removed IDs")));var b=change(2,1,initial()).rubric();assertFalse(b.criteria().stream().anyMatch(n->a.criteria().stream().anyMatch(old->old.criterionId().equals(n.criterionId()))));status(409,()->change(3,1,List.of(new AssignmentRubricInput.Item(f.f.ids.next(),"Forged","",100))));assertEquals(3,history(Long.MAX_VALUE,5).items().size());assertEquals(a,history(2,5).items().getFirst().snapshot());}
 @Test void sourceDefinitionChangesRequireFreshParentVersionAndCanBeExplicitlyReconfirmed(){var a=change(0,1,initial()).rubric();f.store.metadata(f.group,f.space,f.study,assignment,f.f.owner,1,"Changed instruction","New",f.f.trace);status(409,()->change(1,1,items(a,"Changed")));var b=change(1,2,items(a,a.criteria().getFirst().description())).rubric();assertEquals(2,b.assignmentVersion());assertEquals(2,b.version());assertEquals(1,history(2,5).items().getFirst().snapshot().assignmentVersion());}
 @Test void firstOpenPermanentlyFreezesEvenNoOpAndLaterMetadataOrCloseDoNotChangeRubric(){var a=change(0,1,initial()).rubric();f.store.state(f.group,f.space,f.study,assignment,f.f.owner,1,"OPEN",f.f.trace);assertFalse(get().canWrite());status(409,()->change(1,2,items(a,"Edit")));status(409,()->change(1,2,items(a,a.criteria().getFirst().description())));f.store.metadata(f.group,f.space,f.study,assignment,f.f.owner,2,"Corrected instruction","",f.f.trace);f.store.state(f.group,f.space,f.study,assignment,f.f.owner,3,"CLOSED",f.f.trace);status(409,()->change(1,4,List.of()));f.store.state(f.group,f.space,f.study,assignment,f.f.owner,4,"RETIRED",f.f.trace);assertEquals(a,get().rubric());assertEquals(1,history(Long.MAX_VALUE,5).items().size());assertEquals(1,f.events(a.rubricId()));}
 @Test void alreadyOpenWithoutRubricCannotBeRetrofitted(){f.store.state(f.group,f.space,f.study,assignment,f.f.owner,1,"OPEN",f.f.trace);assertNull(get().rubric());status(409,()->change(0,2,initial()));assertNull(get().rubric());}
 @Test void archivedStudyFreezesDraftButCompletedStudyDoesNot(){f.parent.store.state(f.group,f.space,f.study,f.f.owner,1,"ACTIVE",f.f.trace);f.parent.store.state(f.group,f.space,f.study,f.f.owner,2,"COMPLETED",f.f.trace);var a=change(0,1,initial()).rubric();f.parent.store.state(f.group,f.space,f.study,f.f.owner,3,"RETIRED",f.f.trace);assertFalse(get().canWrite());status(409,()->change(1,1,items(a,"After archive")));assertEquals(a,get().rubric());}
 @Test void exactParentScopeAndLocalFksCannotCrossStudyGroupSpace(){var a=change(0,1,initial()).rubric();status(404,()->store.get(f.group,f.space,f.f.ids.next(),assignment,true));status(404,()->store.get(f.group,f.f.ids.next(),f.study,assignment,true));status(404,()->store.get(f.f.ids.next(),f.space,f.study,assignment,true));status(404,()->store.history(f.group,f.space,f.study,f.f.ids.next(),Long.MAX_VALUE,5));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE assignment_rubric SET assignment_version=999999 WHERE rubric_id=?",a.rubricId()));assertEquals(a,get().rubric());}
 @Test void descendingHistoryHasIndependentFiveItemCursor(){var a=change(0,1,initial()).rubric();for(int n=1;n<7;n++)a=change(n,1,items(a,"Description "+n)).rubric();var first=history(Long.MAX_VALUE,5);assertEquals(List.of(7L,6L,5L,4L,3L),first.items().stream().map(AssignmentRubricStore.Revision::version).toList());assertEquals(3L,first.nextBefore());assertEquals(List.of(2L,1L),history(first.nextBefore(),5).items().stream().map(AssignmentRubricStore.Revision::version).toList());}
 @Test void concurrentInitialAndExistingUpdatesHaveExactlyOneWinner()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){for(int round=0;round<2;round++){long base=round;var old=get().rubric();var barrier=new CyclicBarrier(2);var futures=new ArrayList<Future<Boolean>>();for(int n=0;n<2;n++){String reason="Round"+round+"/"+n;var input=old==null?List.of(new AssignmentRubricInput.Item(null,reason,"",100)):items(old,reason);futures.add(pool.submit(()->{barrier.await();try{change(base,1,input);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));}assertNotEquals(futures.get(0).get(20,TimeUnit.SECONDS),futures.get(1).get(20,TimeUnit.SECONDS));}}}
 @Test void concurrentOpenAndEditLeaveExactlyTheDefinitionCommittedBeforeOpen()throws Exception{var original=change(0,1,initial()).rubric();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var edit=pool.submit(()->{barrier.await();try{return change(1,1,items(original,"Concurrent edit")).rubric();}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return original;}});var open=pool.submit(()->{barrier.await();return f.store.state(f.group,f.space,f.study,assignment,f.f.owner,1,"OPEN",f.f.trace);});assertEquals("OPEN",open.get(20,TimeUnit.SECONDS).state());assertEquals(edit.get(20,TimeUnit.SECONDS),get().rubric());assertFalse(get().canWrite());}}
 @Test void outboxFailureRollsBackNewAndExistingDefinitionAndAudit(){String name="rubric_fail_"+assignment.toString().replace("-","");String check=" CHECK(aggregatetype<>'assignment-rubric' OR trace_id<>'"+f.f.trace+"') NOT VALID";f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(0,1,initial()));assertNull(get().rubric());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var a=change(0,1,initial()).rubric();f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(1,1,items(a,"Not saved")));assertEquals(a,get().rubric());assertEquals(1,history(Long.MAX_VALUE,5).items().size());assertEquals(1,f.events(a.rubricId()));}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
}
